import type { JourneyStop, Person } from '../corpus.ts';
import type { LonLat, Year } from '../types.ts';
import type { Content } from './types.ts';

/**
 * Our own people index and journeys (docs/data/content.md): the figures a school history course meets from the Warring
 * States to the founding of the PRC, and the classic journeys told stop by stop. Ids match the imported list where the
 * rest of the app refers to a person or journey by id. `tokens` are the strings that link a chronicle event title to the
 * person; keep them specific (no bare 太宗 or 武帝, which several rulers share).
 */
type T = readonly [string, string];
const L = ([zh, en]: T) => ({ zh, en });

const p = (id: string, name: T, title: T, dyn: string, span: [Year, Year], aliases: string[], tokens: string[], bio: T, fl?: boolean): Person => ({
  id, name: L(name), title: L(title), dyn, span, aliases, tokens: [...new Set(tokens)], bio: L(bio), ...(fl ? { fl: true } : {}),
});

